package com.rescuefarm.ui.checkout;
import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.annotation.*;import androidx.fragment.app.Fragment;import androidx.lifecycle.ViewModelProvider;import androidx.navigation.Navigation;import com.rescuefarm.R;import com.rescuefarm.domain.enums.*;import com.rescuefarm.domain.model.Cart;import java.text.NumberFormat;import java.util.*;
public class CheckoutFragment extends Fragment{private CheckoutViewModel vm;private EditText name,phone,address,lat,lng,note;private Spinner fulfillment,payment;private TextView summary,message;@Nullable public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup p,@Nullable Bundle s){return i.inflate(R.layout.fragment_checkout,p,false);}@Override public void onViewCreated(@NonNull View v,@Nullable Bundle s){name=v.findViewById(R.id.checkoutName);phone=v.findViewById(R.id.checkoutPhone);address=v.findViewById(R.id.checkoutAddress);lat=v.findViewById(R.id.checkoutLatitude);lng=v.findViewById(R.id.checkoutLongitude);note=v.findViewById(R.id.checkoutNote);fulfillment=v.findViewById(R.id.checkoutFulfillment);payment=v.findViewById(R.id.checkoutPayment);summary=v.findViewById(R.id.checkoutSummary);message=v.findViewById(R.id.checkoutMessage);fulfillment.setAdapter(new ArrayAdapter<>(requireContext(),android.R.layout.simple_spinner_dropdown_item,FulfillmentType.values()));payment.setAdapter(new ArrayAdapter<>(requireContext(),android.R.layout.simple_spinner_dropdown_item,PaymentMethod.values()));vm=new ViewModelProvider(this,new CheckoutViewModelFactory(requireContext())).get(CheckoutViewModel.class);((TextView)v.findViewById(R.id.checkoutOwnerText)).setText(vm.isGuest()?R.string.guest_checkout_notice:R.string.customer_checkout_notice);vm.getCart().observe(getViewLifecycleOwner(),this::renderCart);vm.getState().observe(getViewLifecycleOwner(),x->{message.setText(x.getMessage());v.findViewById(R.id.submitCheckoutButton).setEnabled(x.getStatus()!=CheckoutState.Status.LOADING);if(x.getStatus()==CheckoutState.Status.SUCCESS&&vm.consumeCheckoutSuccessNavigation()){Bundle b=new Bundle();b.putString("orderId",x.getOrder().getId());b.putString("orderCode",x.getOrder().getOrderCode());b.putString("phone",x.getOrder().getReceiverPhone());b.putString("status",x.getOrder().getStatus().name());Navigation.findNavController(v).navigate(R.id.action_checkoutFragment_to_orderConfirmationFragment,b);}else if(x.getStatus()==CheckoutState.Status.ERROR)Toast.makeText(requireContext(),x.getMessage(),Toast.LENGTH_LONG).show();});v.findViewById(R.id.submitCheckoutButton).setOnClickListener(x->vm.submit(text(name),text(phone),text(address),text(lat),text(lng),(FulfillmentType)fulfillment.getSelectedItem(),(PaymentMethod)payment.getSelectedItem(),text(note)));}private void renderCart(Cart c){if(c==null)return;int n=0;Set<String>s=new HashSet<>();for(com.rescuefarm.domain.model.CartItem i:c.getItems())if(i.isSelected()){n++;s.add(i.getSellerId());}summary.setText(getString(R.string.checkout_summary_format,n,s.size(),NumberFormat.getCurrencyInstance(new Locale("vi","VN")).format(c.calculateSubtotal())));}private String text(EditText e){return e.getText().toString().trim();}}
